SET default_transaction_read_only = on;
\copy (WITH keys AS (SELECT DISTINCT ticker, alert_date FROM mi_live_trades WHERE account_mode = 'live' AND signal_type = 'magna53' AND filled_at IS NOT NULL AND (filled_at AT TIME ZONE 'America/New_York')::date >= DATE '2026-08-16' UNION SELECT DISTINCT ticker, alert_date FROM mi_orb_shadow_trades WHERE bar_size_minutes = 5 AND status IN ('closed', 'open') AND NOT quarantined AND signal_type = 'magna53' AND alert_date >= DATE '2026-08-17') SELECT k.ticker, k.alert_date, AVG((d.high_price - d.low_price) / NULLIF(d.close, 0) * 100) AS adr_pct, COUNT(d.close) AS n_days FROM keys k LEFT JOIN LATERAL (SELECT dc.high_price, dc.low_price, dc.close FROM mi_daily_closes dc WHERE dc.ticker = k.ticker AND dc.trade_date < k.alert_date AND dc.high_price IS NOT NULL AND dc.low_price IS NOT NULL ORDER BY dc.trade_date DESC LIMIT 20) d ON true GROUP BY k.ticker, k.alert_date ORDER BY k.alert_date, k.ticker) TO STDOUT WITH CSV HEADER
